def lps(s: str) -> int:
    n = len(s)

    # Create a 2D array to store the length of the longest palindromic subsequence
    dp = [[0 for _ in range(n)] for _ in range(n)]

    # Every sequence of length 1 is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the DP table
    for cl in range(2, n + 1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if cl == 2:
                if s[i] == s[j]:
                    dp[i][j] = 2
                else:
                    dp[i][j] = 1
            else:
                if s[i] == s[j]:
                    dp[i][j] = 2 + dp[i + 1][j - 1]
                else:
                    dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    return dp[0][n - 1]

